begin;
set local lock_timeout='3s';
set local statement_timeout='30s';
commit;
select s.name, count(p.id) as products from public.stores s left join public.products p on p.store_id=s.id where s.id in ('f69b9e53-27ff-5123-a58b-220135435c93','39120aef-18da-5bc1-9a5c-91c86d5432cd','b58050f2-ecb1-52a2-8d7e-b67a69c22a3e','73789b2e-69b9-5317-b974-669f4ebf81c9') group by s.id,s.name order by s.name;
